-- ---- short-sharp-sting/sql/010-factions.sql ----
-- User-approved labelled faction defaults; original numerical values are unverified.
-- Source actors: only npc_faction_id changes; primaryfaction remains zero.
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
START TRANSACTION;
CREATE TEMPORARY TABLE _sting_faction_guard(label VARCHAR(80)PRIMARY KEY,ok TINYINT NOT NULL,CHECK(ok=1))ENGINE=InnoDB;
UPDATE npc_types SET npc_faction_id=396942 WHERE id IN(395224,395225,395226,395229,395235,395236,395256,396107,396126,396129,396133,396135,396137,396173,396176,396185,396189,396196,396200,396202,396214,396219,396221,396227,396231,396251);
DROP TEMPORARY TABLE _sting_faction_guard;
COMMIT;

