-- ---- short-sharp-sting/sql/040-parent-rewards.sql ----
-- Staged Short Sharp Sting parent items; no invented parent XP/AA/cash.
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
START TRANSACTION;
CREATE TEMPORARY TABLE _bixie_guard(label VARCHAR(80)PRIMARY KEY,ok TINYINT NOT NULL,CHECK(ok=1))ENGINE=InnoDB;
ON DUPLICATE KEY UPDATE `title`=VALUES(`title`),`enabled`=VALUES(`enabled`);
ON DUPLICATE KEY UPDATE `reward_set_id`=VALUES(`reward_set_id`),`enabled`=VALUES(`enabled`);
ON DUPLICATE KEY UPDATE `sequence`=VALUES(`sequence`),`label`=VALUES(`label`),`common_to_all`=VALUES(`common_to_all`),`flags`=VALUES(`flags`),`enabled`=VALUES(`enabled`),`class_mask`=VALUES(`class_mask`);
ON DUPLICATE KEY UPDATE `sequence`=VALUES(`sequence`);
ON DUPLICATE KEY UPDATE `reward_type`=VALUES(`reward_type`),`reward_data_id`=VALUES(`reward_data_id`),`amount`=VALUES(`amount`),`description`=VALUES(`description`),`enabled`=VALUES(`enabled`);
DROP TEMPORARY TABLE _bixie_guard;
COMMIT;

-- ---- short-sharp-sting/sql/090-activate.sql ----
-- Final activation is part of the same required transaction as every other SQL file.
-- Only the installer supplies the hash after checking the reviewed Lua settings.
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
START TRANSACTION;
CREATE TEMPORARY TABLE _sting_activation_guard(label VARCHAR(80)PRIMARY KEY,ok TINYINT NOT NULL,CHECK(ok=1))ENGINE=InnoDB;
-- NMS: enable the parent achievement(s) (upstream DB carried them enabled
-- from earlier steps our flow does not reproduce).
UPDATE achievements SET enabled=1 WHERE id=500030300;
UPDATE tasks SET enabled=1 WHERE id BETWEEN 3040317 AND 3040320;
UPDATE tradeskill_recipe SET enabled=1 WHERE id=3040320;
UPDATE achievement_criteria SET enabled=1 WHERE achievement_id=500030300 AND component_type=1 AND component_id BETWEEN 50091 AND 50094;
UPDATE reward_sets SET enabled=1 WHERE reward_set_id IN(3040319,3050303);
UPDATE reward_sources SET enabled=1 WHERE(source_type=2 AND source_id=3040319)OR(source_type=1 AND source_id=500030300);
UPDATE reward_options SET enabled=1 WHERE reward_set_id IN(3040319,3050303);
UPDATE rewards SET enabled=1 WHERE reward_id BETWEEN 30403191 AND 30403193 OR reward_id BETWEEN 305030301 AND 305030304;
DROP TEMPORARY TABLE _sting_activation_guard;
COMMIT;
